INSERT OR REPLACE INTO posts (id, created_at, content_es, content_en, image_urls) VALUES ('a6b7c8d9-1234-4567-890a-klipcodepost1', '2026-03-31T10:05:00.000000+00:00', 'He participado en la Hackaton de Midudev y CubePath con un nuevo proyecto en el que he estado trabajando los últimos días: KlipCode, un gestor de snippets.', 'I''ve participated in the Midudev and CubePath Hackathon with a new project I''ve been working on for the past few days: KlipCode, a snippet manager.', '["/imgs/posts/klipcode-img.png"]');
