INSERT OR REPLACE INTO posts (id, created_at, content_es, content_en, image_urls) VALUES ('c8c991ed-5768-4840-822a-a30b23434095', '2026-02-25T13:15:44.249528+00:00', 'Oficialmente RANKMAKER y esta web son open source! El espíritu del software libre me ha poseído y también liberaré la web de Octopus Control y mi ERP personal en los próximos días.', 'Officially, RANKMAKER and this website are now open source! The spirit of free software has possessed me; I will also release the Octopus Control website and my personal ERP in the coming days.', '[]');
INSERT OR REPLACE INTO posts (id, created_at, content_es, content_en, image_urls) VALUES ('3f9e2b7c-5d8a-4a1b-9c2e-0f4a1b2c3d4e', '2026-04-09T11:51:51.000000+02:00', 'Las votaciones de la hackatón en la que participé ya han tenido lugar, y aunque no haya llegado a ser finalista, estoy muy contento de haber estado en las menciones honoríficas y de que mi proyecto haya aparecido en el stream de Midudev. https://www.youtube.com/live/tMatrUSTV9k?si=gID8HfZTTPD7bSTj&t=2218', 'The hackathon votes I participated in have already taken place, and although I didn''t reach the finals, I''m very happy to have been in the honorable mentions and that my project appeared on Midudev''s stream. https://www.youtube.com/live/tMatrUSTV9k?si=gID8HfZTTPD7bSTj&t=2218', '[]');
INSERT OR REPLACE INTO posts (id, created_at, content_es, content_en, image_urls) VALUES ('d4f3a2b1-9c8e-4a2b-9f0a-1234567890ab', '2026-04-04T13:41:00.000000+02:00', 'Acabo de lanzar un miniproyecto para reproducir ruido marrón y blanco. Es bastante simple, pero conseguir el loop infinito del audio sin que se escuchen cortes y construir la APK han sido todo un dolor de cabeza. No liberaré la APK de momento al ser un proyecto sólo para mí mismo, pero está todo listo para compilarla tú mismo en mi repo público de GitHub. Además puedes probarla desde este enlace: https://noises.olma.workers.dev', 'I just launched a small project to reproduce brown and white noise. It''s quite simple, but getting an infinite audio loop without audible gaps and building the APK has been a real headache. I won''t release the APK for now since it''s just a personal project, but everything is ready for you to compile it yourself from my public GitHub repo. You can also try it from this link: https://noises.olma.workers.dev', '[]');

INSERT OR REPLACE INTO projects (id, created_at, slug, name, is_active, start_date, end_date, url, logo_url, short_description_es, short_description_en, history_es, history_en) VALUES ('e6a2b8c1-1234-4567-890a-klipcode0001', '2026-03-31T10:00:00.000000+00:00', 'klipcode', 'KlipCode', 1, '2026-01-01', NULL, 'https://klipcode.com', '/imgs/projects/klipcode.png', 'KlipCode es un gestor de snippets de código con almacenamiento local y sincronización opcional en la nube. Permite guardar, organizar y copiar fragmentos rápidamente, trabajar con carpetas jerárquicas y fijar elementos importantes.', 'KlipCode is a code snippet manager with local storage and optional cloud synchronization. It allows you to quickly save, organize, and copy snippets, work with hierarchical folders, and pin important items.', 'Tras ver un streaming de uno de mis mayores referentes en el desarrollo web: Midudev, sobre una hackatón, me animé a participar por primera vez en una.

Estuve un par de días pensando qué hacer, finalmente me decidí por una herramienta que a mi mismo me sería de utilidad: un portapapeles de código en la nube.

Normalmente programo en casa con mi ordenador principal o en la biblioteca con un portátil y en ocasiones me gustaría compartir pequeños fragmentos de código de forma temporal y rápida entre mis ordenadores sin tener que recurrir a GitHub.
Hasta ahora utilizaba Notion, pero no me resultaba tan cómodo como me gustaría. Necesitaba algo a lo que pudiese simplemente entrar y pegar, orientado específicamente al código.

Me tomó un poco más de tiempo del que esperaba y no pude añadir todas las funcionalidades que había imaginado. Pero aún así acabe muy satisfecho con el resultado.', 'After watching a stream by one of my biggest inspirations in web development, Midudev, about a hackathon, I decided to participate in one for the first time.

I spent a couple of days thinking about what to create, and finally decided on a tool that would be useful for myself: a cloud-based code clipboard.

Usually, I program at home on my main computer or at the library with a laptop, and sometimes I would like to share small code snippets temporarily and quickly between my computers without having to resort to GitHub.
Until now, I used Notion, but it wasn''t as convenient as I would like. I needed something where I could simply jump in and paste, specifically oriented towards code.

It took a bit longer than I expected, and I couldn''t add all the features I had imagined. But even so, I ended up very satisfied with the result.');
INSERT OR REPLACE INTO projects (id, created_at, slug, name, is_active, start_date, end_date, url, logo_url, short_description_es, short_description_en, history_es, history_en) VALUES ('f8f6ddec-1bde-48f0-8060-6a79846d64d6', '2026-02-09T18:31:21.558248+00:00', 'kenobismo', 'Kenobismo', 0, '2020-01-01', '2023-01-01', 'https://www.instagram.com/kenobismo/', '/imgs/projects/kenobismo-logo.webp', 'Kenobismo fue un proyecto en redes sociales centrado en datos, lore y noticias de Star Wars que más tarde se expandiría a cine en general.', 'Kenobismo was a social media project focused on Star Wars data, lore, and news that later expanded into cinema in general.', 'Aunque antes había tenido algunas cuentas sobre contenido de fútbol, considero que mi carrera como emprendedor comienza en 2020 abriendo una cuenta de Instagram dedicada a subir contenido como curiosidades y noticias de Star Wars: Kenobismo. En esta, por primera vez fui consistente con el contenido y me lo tomé un poco más en serio.

No me fue mal en cuanto a número de seguidores y métricas, pero tenía 16 años, la consistencia me agobió y tampoco veía ningún beneficio en seguir con eso. Antes de cumplir el primer aniversario de la cuenta, la acabé cerrando para tomarme un descanso por un tiempo indefinido.

Pasaron los meses, más de un año quizá, y en 2022 vi un short clave que hablaba de una app para minar Bitcoin. (Parece que esto no tiene nada que ver con Kenobismo, pero espera un poco).

Ya me había interesado por cryptos anteriormente, pero nunca más allá de mirar como Bitcoin subía y bajaba. Tras descargar fascinado la aplicación de minería y empezar a utilizarla, nació una nueva obsesión: las criptomonedas. Veía vídeos, gráficos, de todo.
Un compañero de clase me preguntó qué haría al cumplir 18. Pensé unos segundos y respondí: «Crearme una cuenta en Binance».

Y eso hice, aunque no usé para nada la cuenta de Binance, al final compré cryptos en un cajero y las metí en una wallet. Nada de exchanges.

Todo este interés por las criptomonedas me acabó llevando también a descubrir más sobre inversión en general, finanzas personales y lo más importante: emprendimiento.

Esto último me llevó a su vez de vuelta a Kenobismo. Tenía una buena audiencia, podía tomármelo más en serio y ganar dinero. 

Retomé la cuenta de Instagram con fuerza: consistencia, calidad y un objetivo claro. Empecé a subir también vídeos cortos que resubía a TikTok y YouTube (usaba voz artificial, no la mía).
Así que ahí, oficialmente, decidí emprender (aunque el proyecto ya estaba iniciado de antes).

Instagram y el resto de redes empezaron a crecer bastante bien. Al cabo de un tiempo, TikTok incluso superó a Instagram y tuve meses buenísimos, con cifras de hasta 50 millones de visualizaciones.
La monetización, al menos en TikTok, estaba al caer.

Pocos meses después pude solicitarla, aunque si no recuerdo mal, tuve que esperar uno o dos meses para recibir mi primer pago.
Para poder cobrarlo, me abrí mi primera cuenta bancaria. en Revolut. Ese mes las visualizaciones no fueron las mejores, pero gané unos 40-50 €, que me supieron a gloria.

El mes siguiente gané unos 20 €. Y al siguiente, mis vídeos pasaron de un mínimo de 10.000 visualizaciones (con una media de 50.000) a quedarse todos por debajo de mil. Tuve un shadowban, quizá por el contenido de películas.

Seguí subiendo contenido con la esperanza de que se solucionase, pero nunca lo hizo. Como respuesta a esto, dejé los vídeos cortos en Kenobismo y empecé a subir a una nueva serie de cuentas dedicadas al cine en general y no sólo de Star Wars, ahora con mi voz real.

Subí exactamente 100 vídeos. Lo hice como algo temporal para darle tiempo al shadowban de Kenobismo a recuperarse, no llegué a generar ingresos con este proyecto.

Tras los 100 vídeos, volví a Kenobismo. Decidí empezar a subir allí también vídeos de cine en general; no sólo Star Wars; y además dejé publicar otro tipo de publicaciones para centrarme en los vídeos cortos.

Estuve así unas semanas. Pero el shadowban de TikTok seguía. Decidí que había que hacer algo más. Me expandiría a vídeos largos en YouTube.

Empecé a prepararlo todo para ello, pero justo el día antes de grabar el primer vídeo largo de Kenobismo, vi otro vídeo clave para mi trayectoria: The Wild Project #219 ft Jordi Maquiavello.

Un episodio del podcast hablando de cine durante casi cinco horas. Nunca había visto un podcast tan largo de principio a fin. Este fue el primero y me gustó mucho. Pero llegué a una cruda reflexión: no tenía ni idea de cine. Al menos no tanto para “impartir clases” de él.

Tras pensarlo un poco más y viendo que de todos modos esto no tenía mucho futuro y además odiaba grabarme, lo acabé dejando.

Sin embargo, justo el día después de mi reflexión una nueva idea vino a mi mente — EliteBara.', 'Although I had previously run a few accounts focused on football content, I consider my career as an entrepreneur to have begun in 2020, when I opened an Instagram account dedicated to posting curiosities and news about Star Wars: Kenobismo. It was the first time I was consistent with content and took it a bit more seriously.

I didn’t do badly in terms of followers and metrics, but I was 16 years old, the consistency overwhelmed me, and I didn’t really see any benefit in continuing. Before the account reached its first anniversary, I ended up closing it to take a break for an indefinite period of time.

Months passed—more than a year, perhaps—and in 2022 I came across a key short video that talked about an app for mining Bitcoin. (It may seem like this has nothing to do with Kenobismo, but bear with me.)

I had already been interested in crypto before, but never beyond watching Bitcoin go up and down. After fascinatedly downloading the mining app and starting to use it, a new obsession was born: cryptocurrencies. I watched videos, charts—everything.

A classmate asked me what I would do when I turned 18. I thought for a few seconds and replied, “Open a Binance account.”

And that’s what I did, although I didn’t really use the Binance account at all. In the end, I bought crypto at an ATM and put it into a wallet. No exchanges.

All this interest in cryptocurrencies eventually led me to learn more about investing in general, personal finance, and most importantly: entrepreneurship.

That, in turn, brought me back to Kenobismo. I had a good audience, I could take it more seriously, and I could make money from it.

I relaunched the Instagram account with force: consistency, quality, and a clear goal. I also started posting short videos, which I reuploaded to TikTok and YouTube (using artificial voice, not my own).

So at that point, I officially decided to become an entrepreneur (even though the project had already been started before).

Instagram and the other platforms began to grow quite well. After some time, TikTok even surpassed Instagram, and I had some amazing months, with figures of up to 50 million views.
Monetization—at least on TikTok—was just around the corner.

A few months later I was able to apply for it, although if I remember correctly, I had to wait one or two months to receive my first payment.
To be able to collect it, I opened my first bank account, with Revolut. That month the views weren’t great, but I earned around €40–50, which felt incredible.

The following month I earned around €20. And the month after that, my videos went from a minimum of 10,000 views (with an average of 50,000) to all staying below 1,000. I got shadowbanned, possibly due to movie-related content.

I kept uploading content hoping it would be fixed, but it never was. As a response, I stopped posting short videos on Kenobismo and started uploading to a new set of accounts dedicated to cinema in general, not just Star Wars—this time using my real voice.

I uploaded exactly 100 videos. I did it as something temporary, to give Kenobismo’s shadowban time to recover. I didn’t manage to generate any income from this project.

After those 100 videos, I went back to Kenobismo. I decided to start uploading general cinema videos there as well—not only Star Wars—and I also stopped publishing other types of posts to focus exclusively on short videos.

I stayed like that for a few weeks. But the TikTok shadowban continued. I decided something more had to be done. I would expand into long-form videos on YouTube.

I started preparing everything for it, but just the day before recording the first long Kenobismo video, I came across another key video for my trajectory: The Wild Project #219 ft Jordi Maquiavello.

An episode of the podcast talking about cinema for almost five hours. I had never watched such a long podcast from start to finish. This was the first one, and I really liked it. But I came to a harsh realization: I had no real idea about cinema—at least not enough to “teach” it.

After thinking about it a bit more, and seeing that this didn’t really have much of a future anyway—and that I also hated recording myself—I ended up quitting.

However, just the day after that reflection, a new idea came to my mind — EliteBara.');
INSERT OR REPLACE INTO projects (id, created_at, slug, name, is_active, start_date, end_date, url, logo_url, short_description_es, short_description_en, history_es, history_en) VALUES ('a46b546d-470c-486e-bb56-ed3e61cb7179', '2026-02-10T11:17:17.917428+00:00', 'rankmaker', 'RANKMAKER', 1, '2025-01-01', NULL, 'https://rankmaker.net', '/imgs/projects/rankmaker-logo.webp', 'RANKMAKER es un sitio web que permite crear rankings de diversos temas mediante batallas 1vs1.', 'RANKMAKER is a website that allows you to create rankings on various topics through 1vs1 battles.', 'Un día cualquiera de febrero de 2025, mientras me preparaba para ducharme tras volver de correr, me vino de golpe un recuerdo aleatorio.

Un par de años atrás hice un ranking de pilotos de Fórmula 1 que alguien había compartido en Twitter.

Me fascinó el sistema; no tenía que pensar en el orden exacto desde un primer momento ni hacer una tier list.

Simplemente me daban enfrentamientos 1vs1 y, en función de mis elecciones, salía un ranking.

En su momento no le di mucha importancia, pero por alguna razón, en ese instante me volvió a la cabeza.

Durante la ducha seguí dándole vueltas. No tenía ni idea de programar, pero estaba obsesionado con la IA.

En cuanto salí de la ducha, abrí ChatGPT, jugueteé un rato, y en cuestión de minutos tenía un sistema básico donde podía meter opciones, compararlas entre sí en enfrentamientos y obtener un ranking ordenado.

Me di cuenta de que no había ninguna web que hiciera exactamente eso. Esa era mi oportunidad. Podía dedicarle una semanita a esto y así además desconectar un poco Octopus Control para variar.

Pequé de optimismo con lo de "semanita". No era tan sencillo como ir iterando con ChatGPT. Pero descubrí herramientas más potentes como Cursor o Trae.

Desde que descubrí el concepto de base de datos, pensé que primero haría que todo funcionara en local y más adelante lo conectaría a una base de datos. Pero mi idea de "funcionar en local" era usar localStorage como sustituto a base de datos (sin tener ni idea de lo que estaba haciendo).

Cuando decidí dar el salto e implementar la base de datos, no fue tan simple como decirle a la IA "pasa esto de localStorage a base de datos". Estuve semanas atascado, probando diferentes prompts y estructuras sin éxito. Me harté y empecé de cero.

Esta vez, desde el principio, todo estaría conectado a una base de datos y usaría PHP. Esta vez funcionó, conseguí interactuar con la base de datos.

Volví a diseñarlo todo. Parecía listo para lanzarse públicamente, pero entonces descubrí un error crítico: los enfrentamientos 1vs1 no funcionaban bien. Estaban mal implementados. Intenté arreglarlo mil veces, sin éxito.

Así que empecé otra vez. Ahora sí, con una mejor organización de archivos (tenía un archivo JavaScript de 3000 líneas). Tras varias versiones y más reinicios, decidí usar Astro y React (sin tener mucha idea de como funcionaban). Terminé la versión y la preparé para subirla al hosting.

Pero al ir a hacerlo, descubrí que mi hosting era demasiado básico: solo soportaba PHP y poco más. Otra vez a empezar de cero.

Sin embargo, ya sabía lo que hacía (más o menos), así que en unos días tenía otra versión, esta vez con PHP de nuevo. Mucho más simple de lo que había imaginado al principio, pero lo esencial estaba.

El 6 de junio de 2025 nació finalmente RANKMAKER, después de casi medio año de trabajo dedicado al 100% al proyecto, dejando Octopus Control completamente desatendido.

En realidad, fueron 4 o 5 meses de pruebas, bloqueos y reinicios, para finalmente desarrollar todo en unos pocos días con el enfoque “correcto”.

A pesar de que tras publicarlo las cosas no fueron para nada como esperaba, me volví a llevar un aprendizaje brutal como con EliteBara.

Seguía sin entender demasiado de cómo funcionaba exactamente lo que había hecho, pero los conceptos que aprendí fueron clave para que unos pocos meses después me interesara en aprender desarrollo web y programación de forma convencional.

Actualmente RANKMAKER funciona con Astro tras ser reconstruido desde cero a principios de 2026.', 'On a random day in February 2025, while getting ready for a shower after returning from a run, a random memory suddenly hit me.

A couple of years ago, I made a Formula 1 driver ranking that someone had shared on Twitter.

The system fascinated me; I didn''t have to think about the exact order from the start or make a tier list.

They simply gave me 1vs1 matchups and, based on my choices, a ranking emerged.

At the time, I didn''t give it much importance, but for some reason, at that instant, it came back to me.

During the shower, I kept thinking about it. I had no idea how to program, but I was obsessed with AI.

As soon as I got out of the shower, I opened ChatGPT, played around for a bit, and in a matter of minutes, I had a basic system where I could enter options, compare them in matchups, and get an ordered ranking.

I realized there was no website that did exactly that. That was my opportunity. I could spend a week on this and also disconnect a bit from Octopus Control for a change.

I was overoptimistic about the "week" part. It wasn''t as simple as iterating with ChatGPT. But I discovered more powerful tools like Cursor or Trae.

Ever since I discovered the concept of databases, I thought I would first make everything work locally and later connect it to a database. But my idea of "working locally" was using localStorage as a substitute for a database (without having any idea what I was doing).

When I decided to take the leap and implement the database, it wasn''t as simple as telling the AI "move this from localStorage to a database." I was stuck for weeks, trying different prompts and structures without success. I got fed up and started from scratch.

This time, from the beginning, everything would be connected to a database and I would use PHP. This time it worked; I managed to interact with the database.

I redesigned everything. It seemed ready for public launch, but then I discovered a critical error: the 1vs1 matchups didn''t work properly. They were poorly implemented. I tried to fix it a thousand times, without success.

So I started again. This time, with better file organization (I had a 3000-line JavaScript file). After several versions and more restarts, I decided to use Astro and React (without having much of an idea how they worked). I finished the version and prepared to upload it to the hosting.

But when I went to do it, I discovered my hosting was too basic: it only supported PHP and little else. Starting over again.

However, I already knew what I was doing (more or less), so in a few days I had another version, this time with PHP again. Much simpler than I had initially imagined, but the essentials were there.

On June 6, 2025, RANKMAKER was finally born, after almost half a year of 100% dedicated work to the project, leaving Octopus Control completely unattended.

In reality, it was 4 or 5 months of testing, blocks, and restarts, to finally develop everything in a few days with the "correct" approach.

Despite things not going at all as expected after publishing, I took away a brutal learning experience just like with EliteBara.

I still didn''t quite understand exactly how what I had made worked, but the concepts I learned were key to making me interested in learning web development and programming conventionally a few months later.

Currently, RANKMAKER runs on Astro after being rebuilt from scratch in early 2026.');
INSERT OR REPLACE INTO projects (id, created_at, slug, name, is_active, start_date, end_date, url, logo_url, short_description_es, short_description_en, history_es, history_en) VALUES ('b8e14de9-79bf-42e2-a38c-49499e299cf0', '2026-02-10T11:17:15.917428+00:00', 'octopus-control', 'Octopus Control', 1, '2024-01-01', NULL, 'https://octopuscontrol.com', '/imgs/projects/octopus-control.svg', 'Octopus Control es un comercio electrónico especializado en la venta de mandos a distancia para televisores y dispositivos de streaming.', 'Octopus Control is an e-commerce specialized in the sale of remote controls for televisions and streaming devices.', 'Meses después tras dejar EliteBara, estuvo rondando mi cabeza comprar productos al por mayor y venderlos en Wallapop.

En julio de 2024, tras una ardua búsqueda de productos y proveedores, me animé a pedir un poco stock variado, mayoritariamente mandos para Fire TV.

Un par de días después de publicar los anuncios, llegó mi primera venta. Curiosamente, fue el 13 de julio de 2024, justo un año después del nacimiento de EliteBara.

Fui comprando más stock a lo largo de las semanas y vendiéndolo, ajustando precios para optimizar rentabilidad.

Con el tiempo me fui centrando cada vez más en mandos a distancia. Era lo más rentable.

Todo iba bien, creciendo mes tras mes hasta que en octubre llegó mi primer revés: mi cuenta de Wallapop fue suspendida.

Al principio no me preocupé demasiado. Era evidentemente un error y me la devolverían de inmediato.

Les escribí para comunicárselo, pero su respuesta fue que no había error. Aunque lo que argumentaban no tenía ningún sentido.

Seguí insistiendo. Rechazo tras rechazo. Envié mensajes, usé organismos externos, hasta una carta. La única carta física que he mandado en mi vida. Incluso pensé en presentarme en sus oficinas en Barcelona.

Tras dos semanas angustiosas, cuando ya todo parecía perdido, les amenacé con acciones legales. Y entonces, quizá agotados de mi insistencia o asustados por mi farol (probablemente lo primero), me llegó un correo: Admitieron que habían cometido un error y me devolvieron la cuenta. Había ganado.

Ese momento marcó un antes y un después. Para empezar, esto no podía seguir siendo un proyecto sin nombre y que únicamente dependía de Wallapop.

Por lo que nació oficialmente Octopus Control. Empecé a vender en otras plataformas de segunda mano y creé una web con Shopify. No mucho después del rebranding, logré volver al nivel de ingresos anterior al cierre de la cuenta.

Un par de meses más tarde, ya empecé a preocuparme por impuestos y legalidades. En diciembre, lo oficialicé todo y me di de alta como autónomo.

A día de hoy, sigue generando ingresos recurrentes que me permiten pagar gastos e invertir en otros negocios.

Recientemente dejé de vender en la web de Octopus Control para usarla únicamente como catálogo.', 'Months after leaving EliteBara, I had the idea of buying products wholesale and selling them on Wallapop.

In July 2024, after an arduous search for products and suppliers, I decided to order some varied stock, mostly remotes for Fire TV.

A couple of days after posting the ads, my first sale arrived. Curiously, it was on July 13, 2024, exactly one year after the birth of EliteBara.

I kept buying more stock over the weeks and selling it, adjusting prices to optimize profitability.

Over time, I focused more and more on remote controls. It was the most profitable.

Everything was going well, growing month after month until my first setback arrived in October: my Wallapop account was suspended.

At first, I didn''t worry too much. It was clearly an error and they would return it immediately.

I wrote to them to let them know, but their response was that there was no error. Although their arguments made no sense.

I kept insisting. Rejection after rejection. I sent messages, used external organizations, even a letter. The only physical letter I have sent in my life. I even thought about showing up at their offices in Barcelona.

After two harrowing weeks, when everything seemed lost, I threatened them with legal action. And then, perhaps exhausted by my insistence or scared by my bluff (probably the former), an email arrived: they admitted they had made an error and returned the account to me. I had won.

That moment marked a before and after. For starters, this couldn''t continue being a nameless project that only depended on Wallapop.

So, Octopus Control was officially born. I started selling on other second-hand platforms and created a website with Shopify. Not long after the rebranding, I managed to return to the income level prior to the account closure.

A couple of months later, I started worrying about taxes and legalities. In December, I formalized everything and registered as self-employed.

Today, it continues to generate recurring income that allows me to pay expenses and invest in other businesses.

Recently, I stopped selling on the Octopus Control website to use it solely as a catalog.');
INSERT OR REPLACE INTO projects (id, created_at, slug, name, is_active, start_date, end_date, url, logo_url, short_description_es, short_description_en, history_es, history_en) VALUES ('e7fd4d08-004c-4bba-8c15-a751908dda73', '2026-02-10T11:17:17.917428+00:00', 'elitebara', 'EliteBara', 0, '2023-01-01', '2023-01-01', NULL, '/imgs/projects/elitebara-logo.webp', 'EliteBara fue una tienda online de ropa con una peculiar temática de capibaras.', 'EliteBara was an online clothing store with a peculiar capybara theme.', 'Paralelamente a Kenobismo, estuve subiendo contenido sobre capibaras en una cuenta de Instagram sin darle mucha importancia, sólo por si algún día quería vender algo relacionado con capibaras y así ya tener una audiencia.

Tras dejar la creación de contenido de cine era hora de hacer algo un poco más serio que simplemente crear contenido en redes sociales. Empezaría a vender ese algo relacionado con capibaras ya. Ropa.

No tenía ningún interés en especial por la ropa, ni siquiera a nivel personal. Pero mi limitada visión empresarial de la época no veía posible emprender de otra manera.

Tras unas semanas aprendiendo lo justo, diseñando camisetas y configurando Shopify, el 13 de julio de 2023 nació EliteBara, mi proyecto más serio hasta el momento.

Para dar a conocer la marca lancé un sorteo en colaboración con la cuenta de capibaras que había creado antes. Lo que pensé que resultaría, sin lugar a dudas, en una buena inyección de tráfico a las redes de EliteBara y la web, acabó siendo en realidad, un sorteo muerto de dos o tres personas.

El resto del proyecto fue igual de bien que el sorteo: mal. Logré una sola venta de la que apenas me llevé un euro.

Las camisetas que había pedido tenían una calidad de impresión cuestionable que no justificaba el precio que necesitaba poner a las prensas para no perder dinero.

Empecé el proyecto con unos míseros 50 €, pensando inocentemente que sería más que suficiente. Pero la primera y única venta que hice, ni siquiera pude enviarla al momento y tuve que esperar varios días a que Shopify me ingresara el dinero porque no tenía para pagar el producto a Printful.

Temía que hubiese una devolución, algo bastante probable con una tienda de ropa y más teniendo en cuenta la calidad.

Con mi caja tan reducida, eso podría haberme causado un problema serio. Lo más sensato fue cerrarlo todo tras un par de meses, aunque ni siquiera hubiese tenido el dinero en el caso de querer continuar para pagar la suscripción de Shopify tras los tres meses de prueba.

A pesar de todo, el conocimiento adquirido en el proceso es invaluable, por lo que nunca lo vi como un fracaso.', 'In parallel with Kenobismo, I had been uploading capybara content to an Instagram account without giving it much importance, just in case one day I wanted to sell something related to capybaras and already have an audience.

After leaving film content creation, it was time to do something a bit more serious than just creating social media content. I would start selling that capybara-related thing now. Clothing.

I had no special interest in clothing, not even on a personal level. But my limited business vision at the time didn''t see any other way to start a business.

After a few weeks of learning just enough, designing t-shirts, and setting up Shopify, EliteBara was born on July 13, 2023, my most serious project to date.

To promote the brand, I launched a giveaway in collaboration with the capybara account I had created before. What I thought would undoubtedly result in a good injection of traffic to EliteBara''s social media and website ended up being, in reality, a dead giveaway with two or three people.

The rest of the project went just as well as the giveaway: poorly. I managed only one sale from which I barely made a euro.

The t-shirts I had ordered had a questionable print quality that didn''t justify the price I needed to set to avoid losing money.

I started the project with a measly €50, innocently thinking it would be more than enough. But the first and only sale I made, I couldn''t even ship it immediately and had to wait several days for Shopify to deposit the money because I didn''t have enough to pay Printful for the product.

I feared there would be a return, something quite likely with a clothing store and even more so considering the quality.

With my cash flow so reduced, that could have caused a serious problem. The most sensible thing was to close everything after a couple of months, even if I wouldn''t have had the money to continue paying for the Shopify subscription after the three-month trial.

Despite everything, the knowledge gained in the process is invaluable, so I never saw it as a failure.');
INSERT OR REPLACE INTO projects (id, created_at, slug, name, is_active, start_date, end_date, url, logo_url, short_description_es, short_description_en, history_es, history_en) VALUES ('6d41514a-46b0-4cd6-8c4c-b3d90be99743', '2026-02-10T11:17:17.917428+00:00', 'goal-partner', 'Goal: Partner.', 0, '2025-01-01', '2025-01-01', 'https://goalpartner.4oli.com', '/imgs/projects/goal-partner-logo.webp', 'Goal: Partner. fue una plataforma de citas de cortísima vida enfocada en ofrecer un servicio sano, honesto y transparente.', 'Goal: Partner. was a short-lived dating platform focused on offering a healthy, honest, and transparent service.', 'Nunca había tenido el más mínimo conocimiento sobre plataformas de citas, pero tras leer una reseña de una aplicación de este tipo que decía «Es como el resto de apps, ganan dinero de tus fracasos», se me encendió la lucecilla de emprendedor en mi cabeza y decidí que tenía que crear la verdadera alternativa.

Por primera vez iba a emprender un proyecto desde la necesidad ajena en lugar de la propia. ¿Qué podía salir mal?

No tardé mucho en ponerme a crearla, por suerte ya tenía los conocimientos para crear una plataforma usando Inteligencia Artificial gracias a RANKMAKER.

RANKMAKER no tenía inicio de sesión, aquí lo necesitaría sí o sí, pero por suerte mi mayor entendimiento y mejora de los LLM compensaron el aumento de dificultad.

Sin embargo, fui extremadamente vago en el desarrollo de la web. No es sólo que no supiese lo que estaba haciendo, sino que además no me importaba demasiado. Me encontraba en una época de mi vida algo distraída y eso resintió considerablemente el producto.

Lo conseguí lanzar un par de meses después aunque podría haberlo hecho mucho antes y mejor si tan sólo hubiese estado un poco más concentrado.

Puse unos anuncios en Instagram, pero un par de días después me di cuenta que la plataforma no funcionaba correctamente. No recuerdo que función exacta era la que no funcionaba, si los likes o el inicio de sesión, pero era algo crítico.

Corté de inmediato la inversión en anuncios y empecé de una vez por todas a aprender programación.

Pensé que una vez adquiriese los conocimientos necesarios retomaría el proyecto. Pero con el paso del tiempo, y viéndolo de una forma más fría. Descubrí que montar una plataforma de citas con unos pocos cientos de euros era bastante ingenuo, deseché por completo la idea.

A pesar de que la idea tanto conceptual como de funcionamiento no eran del todo malas, el mundo no necesita otra plataforma de citas.', 'I had never had the slightest knowledge about dating platforms, but after reading a review of such an app that said "It''s like the rest of the apps, they make money from your failures," the entrepreneurial light bulb went off in my head and I decided I had to create the true alternative.

For the first time, I was going to undertake a project based on someone else''s needs instead of my own. What could go wrong?

It didn''t take long for me to start creating it; luckily I already had the knowledge to create a platform using Artificial Intelligence thanks to RANKMAKER.

RANKMAKER didn''t have a login; here I would need it for sure, but luckily my increased understanding and improvement of LLMs compensated for the increased difficulty.

However, I was extremely lazy in the web development. It wasn''t just that I didn''t know what I was doing, but I also didn''t care too much. I was in a somewhat distracted period of my life and that considerably affected the product.

I managed to launch it a couple of months later, although I could have done it much sooner and better if I had only been a bit more focused.

I ran some Instagram ads, but a couple of days later I realized the platform wasn''t working correctly. I don''t remember the exact function that didn''t work, whether it was the likes or the login, but it was something critical.

I immediately cut the investment in ads and started learning programming once and for all.

I thought that once I acquired the necessary knowledge I would resume the project. But as time passed, and looking at it more coldly, I discovered that building a dating platform with a few hundred euros was quite naive; I completely scrapped the idea.

Despite the fact that both the conceptual and functional ideas weren''t all bad, the world doesn''t need another dating platform.');
INSERT OR REPLACE INTO projects (id, created_at, slug, name, is_active, start_date, end_date, url, logo_url, short_description_es, short_description_en, history_es, history_en) VALUES ('fc744855-9f48-4e70-83d3-4f37edfd481a', '2026-03-21T15:33:38.506951+00:00', 'oliverp', 'OlivERP', 1, '2025-01-21', NULL, 'https://github.com/martinezharo/erp', '/imgs/projects/oliverp-logo.webp', 'OlivERP es mi ERP personal que uso para mis proyectos, principalmente Octopus Control.', 'OlivERP is my personal ERP that I use for my projects, mainly Octopus Control.', 'Realmente nunca consideré esta herramienta personal como un proyecto más, nació en verano de 2025 como alternativa a una gigantesca e incomoda hoja de Google Sheets, se mantuvo con diseño y funcionalidades similares hasta principios de 2026.
Cuando, aprovechando que mi plan anual de Hostinger caducaba, la rehice desde cero para poder desplegarla en Cloudflare y además mejorar considerablemente la UI.

Es entonces cuando también decidí hacer público el repositorio en GitHub con licencia MIT, y que esta herramienta que tanto me había servido a mi, pudiese ser también de utilidad a otros pequeños negocios.

OlivERP es totalmente gratis y actualmente no tiene intención de comercializarse.', 'I never truly considered this personal tool as just another project; it was born in the summer of 2025 as an alternative to a massive and clunky Google Sheets file, maintaining similar design and features until early 2026.

When my Hostinger annual plan was about to expire, I took the opportunity to rebuild it from scratch to deploy it on Cloudflare and significantly improve the UI.

That is also when I decided to make the GitHub repository public under the MIT license, so this tool that had served me so well could also be useful to other small businesses.

OlivERP is completely free and there is currently no intention to commercialize it.');
INSERT OR REPLACE INTO projects (id, created_at, slug, name, is_active, start_date, end_date, url, logo_url, short_description_es, short_description_en, history_es, history_en) VALUES ('310b86f9-4229-409e-90ce-b0c01a07d09d', '2026-06-08T10:32:00.000000+02:00', 'fewya', 'Fewya', 1, '2026-01-01', NULL, 'https://fewya.com', '/imgs/projects/fewya-logo.svg', 'Fewya es un marketplace especializado en productos nuevos de vendedores profesionales.', 'Fewya is a marketplace specialized in new products from professional sellers.', 'Antes de empezar con Octopus Control había descubierto una forma de vender online de la que nadie estaba hablando: marketplaces como Wallapop y Vinted.

Pero no para usarlos como nacieron, vendiendo productos de segunda mano que te sobran por casa; tampoco para comprar productos allí, restaurarlos y revenderlos. Mi idea era comprar productos al por mayor (en cualquier sitio) y venderlos en esas plataformas. Lo mismo que haría en un e-commerce tradicional con su propia web o en Amazon, pero con la diferencia de que aquí ya tendría clientes con intención de compra y no necesitaría complejísimas configuraciones.

Y no salió mal del todo. Pero definitivamente esto no estaba siendo tan eficiente como debería.

¿Gestionar stock? Olvídate. Tendrás que volver a subir el anuncio tras cada venta.

¿Variantes? Nope. Tendrás que conformarte con subir un nuevo anuncio y esperar a que a tu cliente le aparezca casualmente la mejor opción para él.

¿Qué pasa si un cliente quiere varias unidades de un producto o comprar varios artículos tuyos? Pues... ¡sube un nuevo anuncio solo para él!

¿Era esto lo peor? No, definitivamente no.

"¿Sigue disponible?", "¿Cuál es el precio?", "Hola", "¿Haces envíos?", "Te ofrezco 5 €", "Estoy interesado", "¿Es nuevo?"...

Si quieres vender profesionalmente, este será tu pan de cada día. Ya puedes tener las fotos más profesionales, los mejores textos, un catálogo extenso y cuidado, e incluso estar cotizando en el NASDAQ; para el comprador de estas plataformas serás igual que el resto de vendedores.

Definitivamente no es culpa de los compradores. Dudo mucho que, cuando compran en Amazon, también se pongan en contacto con los vendedores para pedir permiso antes de hacerlo.

El problema es la sobrehumanización de estas plataformas. La informalidad y la escasa profesionalidad que se respiran en ellas. Lo interiorizado que está el chat tanto en la plataforma como en la mente de sus usuarios.

Por si todo esto no fuese suficiente, tenemos un último problema, y quizá la causa raíz de todo ello:

No les interesas a las plataformas.

Sí, quizá puedas estar vendiendo cada mes lo mismo que venden 100 vendedores particulares, pero el vendedor profesional es una minoría ridículamente pequeña. Sería un suicidio empresarial empezar a modificar cosas que ya funcionan para la mayoría de sus usuarios y que, además, resultarían contradictorias con su imagen de marca basada en el consumo de segunda mano.

En la otra cara de la moneda tenemos Amazon. No se puede decir que le falte profesionalidad y tampoco hace falta explicar todas las opciones que ofrece a los vendedores.

Quizá puedas encontrar allí esa funcionalidad que necesitas... después de pasar por sus infinitos formularios, completar todas sus verificaciones, sufrir una interfaz propia de los años 90 (lo siento Jeff, pero ya va tocando renovarla) y rezar lo suficiente para no cometer ningún error que termine con tu cuenta suspendida de por vida.

A pesar de todo, supongamos que has conseguido completar toda la configuración inicial y superar a la competencia para lograr tus primeras ventas. Pero...

¿Recuerdas lo que dije sobre la sobrehumanización de Wallapop y Vinted? Pues en Amazon nos vamos al extremo contrario.

¿Alguien es realmente consciente de la tienda a la que está comprando?

Sabes que compras en Amazon, cuánto ha tardado en llegar tu paquete y quizá conoces la marca del producto. Pero Amazon pone las cosas realmente difíciles para que el comprador sepa que has sido tú quien ha realizado la venta.

En Amazon serás solo precio.

Wallapop y Vinted sobrehumanizan la transacción, mientras que Amazon te deshumaniza como vendedor.

Aquí es donde entra Fewya.

Un marketplace con la facilidad para vender de las plataformas ya comentadas, pero con la atención que necesitan esos emprendedores que acaban de empezar o esas tiendas físicas que quieren comenzar a vender online al resto del mundo.', 'Before starting Octopus Control, I had discovered a way of selling online that nobody was talking about: marketplaces like Wallapop and Vinted.

But not to use them the way they were intended—selling the second-hand products lying around your house; nor to buy products there, restore them, and resell them. My idea was to buy products wholesale (anywhere) and sell them on those platforms. The same thing I would do in a traditional e-commerce store with its own website or on Amazon, but with the difference that here I would already have customers with the intention to buy and wouldn''t need extremely complex configurations.

And it didn''t go badly at all. But this definitely wasn''t being as efficient as it should be.

Manage stock? Forget it. You''ll have to re-upload the listing after every sale.

Variants? Nope. You''ll have to settle for uploading a new listing and hope your customer happens to come across the best option for them.

What happens if a customer wants several units of a product or to buy several of your items? Well... upload a new listing just for them!

Was this the worst part? No, definitely not.

"Is it still available?", "What''s the price?", "Hi", "Do you ship?", "I''ll offer you €5", "I''m interested", "Is it new?"...

If you want to sell professionally, this will be your bread and butter. You can have the most professional photos, the best copy, an extensive and carefully curated catalog, and even be listed on the NASDAQ; to the buyer on these platforms, you''ll be just like every other seller.

It''s definitely not the buyers'' fault. I highly doubt that, when they buy on Amazon, they also contact the sellers to ask for permission before doing so.

The problem is the over-humanization of these platforms. The informality and the lack of professionalism you breathe in them. How ingrained chat is, both on the platform and in the minds of its users.

As if all this weren''t enough, we have one last problem, and perhaps the root cause of it all:

The platforms aren''t interested in you.

Yes, you might be selling the same amount each month as 100 private sellers, but the professional seller is a ridiculously small minority. It would be business suicide to start changing things that already work for the majority of their users and that would, on top of that, be contradictory to their brand image based on second-hand consumption.

On the other side of the coin, we have Amazon. You can''t say it lacks professionalism, and there''s no need to explain all the options it offers sellers.

Maybe you can find that functionality you need there... after going through its endless forms, completing all its verifications, suffering through an interface straight out of the ''90s (sorry Jeff, but it''s about time for a redesign), and praying hard enough not to make any mistake that ends with your account suspended for life.

Despite everything, let''s suppose you''ve managed to complete all the initial setup and beat the competition to make your first sales. But...

Remember what I said about the over-humanization of Wallapop and Vinted? Well, on Amazon we go to the opposite extreme.

Is anyone really aware of the store they''re buying from?

You know you''re buying on Amazon, how long your package took to arrive, and maybe you know the product''s brand. But Amazon makes it really hard for the buyer to know that it was you who made the sale.

On Amazon, you''ll be just a price.

Wallapop and Vinted over-humanize the transaction, while Amazon dehumanizes you as a seller.

This is where Fewya comes in.

A marketplace with the ease of selling of the platforms already mentioned, but with the attention needed by those entrepreneurs who are just starting out, or those brick-and-mortar stores that want to begin selling online to the rest of the world.');
